local NAME='tech-priests-emergency-power-grid'
local function check(v,m)if not v then error('POWER GRID PROOF: '..m)end end
local function C(e,id)return e.get_wire_connector(id,true)end
local function link(a,b,id)local x,y=C(a,id),C(b,id);check(x.can_wire_reach(y),'normal reach');if not x.is_connected_to(y)then check(x.connect_to(y,true,defines.wire_origin.player),'native player-origin wire')end;check(x.is_connected_to(y),'actual connection')end
local function make_power(s,p)return assert(s.create_entity{name='power-grid-proof-power',position=p,force='player'})end
local function snap()local rows={};for _,e in ipairs(storage.inside)do rows[#rows+1]={offset=e.position,energy=e.energy,status=e.status}end;return{inside=rows,relay_load_energy=storage.relay_load.energy,networkA=storage.a.electric_network_id,networkB=storage.b.electric_network_id,copper_connected=C(storage.a,defines.wire_connector_id.pole_copper).is_connected_to(C(storage.b,defines.wire_connector_id.pole_copper))}end
script.on_init(function()
 local s=game.surfaces[1];local f=game.forces.player;game.speed=10;s.request_to_generate_chunks({25,25},3);s.force_generate_chunk_requests();local tiles={};for x=5,48 do for y=5,43 do tiles[#tiles+1]={name='grass-1',position={x,y}}end end;s.set_tiles(tiles,true)
 for _,e in pairs(s.find_entities_filtered{area={{5,5},{48,43}},type={'tree','simple-entity','cliff'}})do e.destroy()end
 storage.samples={};local x,y=20.5,20.5;storage.a=s.create_entity{name=NAME,position={x,y},force=f,raise_built=true};storage.b=s.create_entity{name=NAME,position={x+9,y},force=f,raise_built=true};storage.toofar=s.create_entity{name=NAME,position={x,y+10},force=f,raise_built=true};storage.health=storage.a.health
 check(storage.a.prototype.get_supply_area_distance()==3.5 and storage.a.prototype.get_max_wire_distance()==9 and storage.a.prototype.get_max_circuit_wire_distance()==9,'actual7x7 supply and9tile wire reach');check(storage.a.prototype.tile_width==1 and storage.a.prototype.tile_height==1 and storage.a.health==55,'normal1x1/55health');check(not storage.a.burner and storage.a.fluids_count==0,'passive pole, no fuel/fluids')
 local copper=defines.wire_connector_id.pole_copper;link(storage.a,storage.b,copper);local beyond=C(storage.toofar,copper);check(not C(storage.a,copper).can_wire_reach(beyond)and not C(storage.a,copper).connect_to(beyond,true,defines.wire_origin.player),'direct10tile copper link rejected')
 storage.power=make_power(s,{x=x-2,y=y-2});storage.inside={};storage.outside={}
 for _,dx in ipairs({-3,0,3})do for _,dy in ipairs({-3,0,3})do if dx~=0 or dy~=0 then storage.inside[#storage.inside+1]=s.create_entity{name='small-lamp',position={x+dx,y+dy},force=f}end end end
 for _,d in ipairs({{-4,0},{4,0},{0,-4},{0,4},{-4,-4},{-4,4},{4,-4},{4,4}})do storage.outside[#storage.outside+1]=s.create_entity{name='small-lamp',position={x+d[1],y+d[2]},force=f}end
 check(s.can_place_entity{name='assembling-machine-3',position={x+11,y},force=f},'normal remote consumer placement');storage.relay_load=s.create_entity{name='assembling-machine-3',position={x+11,y},force=f};storage.relay_load.set_recipe('iron-gear-wheel');check(storage.relay_load.insert{name='iron-plate',count=100}==100,'real remote crafting load input')
 storage.signal=s.create_entity{name='constant-combinator',position={x+2,y+1},force=f};local section=storage.signal.get_or_create_control_behavior().add_section();section.set_slot(1,{value={type='virtual',name='signal-A',quality='normal'},min=17});storage.section=section
 for _,id in ipairs({defines.wire_connector_id.circuit_red,defines.wire_connector_id.circuit_green})do link(storage.signal,storage.a,id);link(storage.a,storage.b,id);check(not C(storage.a,id).can_wire_reach(C(storage.toofar,id)),'10tile circuit reach rejected')end
 storage.hold=s.create_entity{name='steel-chest',position={x-3,y+7},force=f}
end)
script.on_event(defines.events.on_tick,function(ev)
 local t=ev.tick;local copper=defines.wire_connector_id.pole_copper
 if storage.complete then
  if t>=storage.complete_tick+360 and not storage.reloaded then storage.reloaded=true;check(storage.a.valid and storage.b.valid and storage.a.health==55,'operated poles persist');check(C(storage.a,copper).is_connected_to(C(storage.b,copper))and storage.relay_load.energy>0,'actual copper network survives reload');for _,wire in ipairs({defines.wire_connector_id.circuit_red,defines.wire_connector_id.circuit_green})do check(storage.b.get_circuit_network(wire).get_signal{type='virtual',name='signal-A',quality='normal'}==23,'real circuit state survives reload')end;helpers.write_file('power-grid-proof/reloaded-state.json',helpers.table_to_json{passed=true,snapshot=snap()},false);log('POWER_GRID_PERSISTENT_STATE_PASS')end;return
 end
 if t==180 then
  for _,e in ipairs(storage.inside)do check(e.energy>0,'inside7x7 ordinary lamps powered')end;for _,e in ipairs(storage.outside)do check(e.energy==0,'outside7x7 lamps remain unpowered')end
  check(storage.a.electric_network_id==storage.b.electric_network_id and storage.relay_load.products_finished>0,'real remote assembler operates through9tile pole link')
  for _,wire in ipairs({defines.wire_connector_id.circuit_red,defines.wire_connector_id.circuit_green})do check(storage.b.get_circuit_network(wire).get_signal{type='virtual',name='signal-A',quality='normal'}==17,'actual red/green circuit signal through pole chain')end;storage.samples.powered=snap()
 elseif t==240 then check(C(storage.a,copper).disconnect_from(C(storage.b,copper),defines.wire_origin.player),'normal copper wire removal')
 elseif t==480 then check(storage.relay_load.energy<.01 and storage.a.electric_network_id~=storage.b.electric_network_id,'relay load actually loses supply after copper cut');storage.cut_products=storage.relay_load.products_finished;storage.samples.copper_cut=snap()
 elseif t==600 then check(storage.relay_load.products_finished==storage.cut_products,'unpowered remote crafting stops');link(storage.a,storage.b,copper)
 elseif t==780 then check(storage.relay_load.energy>0 and storage.relay_load.products_finished>storage.cut_products,'copper reconnection restarts remote crafting');storage.samples.reconnected=snap();storage.power.destroy()
 elseif t==1020 then for _,e in ipairs(storage.inside)do check(e.energy<.01,'real source removal drains local lamps')end;check(storage.relay_load.energy<.01,'real source removal drains relay load');storage.samples.source_removed=snap();storage.power=make_power(storage.a.surface,{x=18.5,y=18.5})
 elseif t==1200 then for _,e in ipairs(storage.inside)do check(e.energy>0,'source restoration repowers supply area')end;check(storage.relay_load.energy>0,'source restoration repowers remote load');storage.section.set_slot(1,{value={type='virtual',name='signal-A',quality='normal'},min=23});storage.samples.source_restored=snap()
 elseif t==1260 then
  for _,wire in ipairs({defines.wire_connector_id.circuit_red,defines.wire_connector_id.circuit_green})do check(storage.b.get_circuit_network(wire).get_signal{type='virtual',name='signal-A',quality='normal'}==23,'live circuit signal updates propagate')end
  local s=storage.a.surface;for _,list in ipairs({storage.inside,storage.outside})do for i=#list,1,-1 do if list[i].position.x==20.5 and list[i].position.y<18 then list[i].destroy();table.remove(list,i)end end end;storage.builder=s.create_entity{name='assembling-machine-3',position={x=20.5,y=17.5},force='player'};storage.builder.set_recipe(NAME);check(storage.builder.insert{name='wood',count=1}==1 and storage.builder.insert{name='copper-plate',count=1}==1,'actual wood/copper building recipe')
 elseif t==1500 then
  local out=storage.builder.get_output_inventory();check(out.remove{name=NAME,count=1}==1,'actual1s crafted pole item consumed');local pos={x=15.5,y=27.5};local s=storage.a.surface;check(s.can_place_entity{name=NAME,position=pos,force='player'},'normal crafted1x1 pole placement');local e=s.create_entity{name=NAME,position=pos,force='player',raise_built=true};check(e.mine{inventory=storage.hold.get_inventory(defines.inventory.chest),raise_destroyed=true},'native pole mining');check(storage.hold.get_inventory(defines.inventory.chest).get_item_count(NAME)==1,'native mining returns crafted item');check(storage.a.health==storage.health,'health retained');storage.complete=true;storage.complete_tick=t
  helpers.write_file('power-grid-proof/operation.json',helpers.table_to_json{passed=true,normal_quality_scope=true,actual_supply_area_7x7_eight_inside_eight_outside_lamps=true,actual9tile_copper_and_circuit_reach=true,direct10tile_links_rejected=true,actual_remote_assembler_produced_items_through_pole_chain=true,actual_copper_cut_stops_and_reconnect_restarts_remote_load=true,real_source_removal_and_resupply=true,native_red_green_signals_17_then23=true,actual_building_recipe_place_mine=true,no_target_or_accumulator_energy_assignments=true,passive_pole_no_fuel_processing_fluid_or_moving_cycle=true,power_fixture='External native test-only EEI provides50MW through the actual target poles. Real lamps and actual remote assembler consume it; no target or accumulator energy assigned.',samples=storage.samples},false);log('POWER_GRID_NATIVE_OPERATIONAL_PASS');if game.is_multiplayer()then game.server_save('power-grid-operated')end
 end
end)
remote.add_interface('power_grid_proof',{layout=function()return{{entity=storage.a,position=storage.a.position,surface=storage.a.surface.index},{entity=storage.b,position=storage.b.position,surface=storage.b.surface.index}}end})
